class Solution {
  public int minimumMoves(int[][] grid) {
    int n = grid.length;
    // state: tail cell (r, c) and orientation (0 horizontal, 1 vertical)
    boolean[][][] seen = new boolean[n][n][2];
    Deque<int[]> queue = new ArrayDeque<>();
    queue.add(new int[] {0, 0, 0});
    seen[0][0][0] = true;
    for (int steps = 0; !queue.isEmpty(); steps++) {
      for (int size = queue.size(); size > 0; size--) {
        int[] s = queue.poll();
        int r = s[0], c = s[1], o = s[2];
        if (r == n - 1 && c == n - 2 && o == 0) return steps;
        if (o == 0) {
          if (c + 2 < n && grid[r][c + 2] == 0) push(queue, seen, r, c + 1, 0);
          if (r + 1 < n && grid[r + 1][c] == 0 && grid[r + 1][c + 1] == 0) {
            push(queue, seen, r + 1, c, 0);
            push(queue, seen, r, c, 1);
          }
        } else {
          if (r + 2 < n && grid[r + 2][c] == 0) push(queue, seen, r + 1, c, 1);
          if (c + 1 < n && grid[r][c + 1] == 0 && grid[r + 1][c + 1] == 0) {
            push(queue, seen, r, c + 1, 1);
            push(queue, seen, r, c, 0);
          }
        }
      }
    }
    return -1;
  }

  private void push(Deque<int[]> queue, boolean[][][] seen, int r, int c, int o) {
    if (!seen[r][c][o]) {
      seen[r][c][o] = true;
      queue.add(new int[] {r, c, o});
    }
  }
}
